export function formatHistoricalResultStory(value, localizers = {}) {
  const parsed = parseHistoricalResultStory(value);
  return parsed
    ? formatLocaleHistoricalResultStory(
        localizeHistoricalResultStoryData(parsed, localizers)
      )
    : "";
}

export default Object.freeze({
  ...CONTENT_METADATA,
  translations: CONTENT_TRANSLATIONS,
  entities: CONTENT_ENTITIES,
  formatHistoricalResultStory
});
